import re
from decimal import Decimal

_MAX_CENTS = 100000000  # 1000000.00
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?", re.ASCII)


def _to_cents(value):
    """Return the exact positive integer number of cents for ``value``.

    Only integer arithmetic and ``Decimal.as_tuple`` are used, so the result
    does not depend on (and never touches) the active decimal context.
    """
    if isinstance(value, bool):
        raise ValueError("invalid amount")
    if isinstance(value, int):
        if value <= 0 or value > _MAX_CENTS // 100:
            raise ValueError("amount out of range")
        return value * 100
    if isinstance(value, str):
        if not _AMOUNT_RE.fullmatch(value):
            raise ValueError("invalid amount string")
        value = Decimal(value)  # construction from str is always exact
    elif not isinstance(value, Decimal):
        raise ValueError("unsupported amount type")

    if not value.is_finite():
        raise ValueError("amount must be finite")
    sign, digits, exp = value.as_tuple()
    coef_digits = list(digits)
    while len(coef_digits) > 1 and coef_digits[-1] == 0:
        coef_digits.pop()
        exp += 1
    if all(d == 0 for d in coef_digits):
        raise ValueError("amount must be positive")
    if sign:
        raise ValueError("amount must be positive")
    while coef_digits and coef_digits[0] == 0:
        coef_digits.pop(0)
    if exp < -2:
        raise ValueError("amount not representable in cents")
    if len(coef_digits) + exp - 1 > 6:  # magnitude >= 10**7
        raise ValueError("amount too large")
    cents = int("".join(map(str, coef_digits))) * 10 ** (exp + 2)
    if cents > _MAX_CENTS:
        raise ValueError("amount too large")
    return cents


def _from_cents(cents):
    return Decimal((0, tuple(int(c) for c in str(cents)), -2))


def parse_amount(value):
    return _from_cents(_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
EOF
